 MainHost h;int passed;String phase;final String day="2026-12-15";
 @Override public void onCreate(Bundle b){super.onCreate(b);phase=b==null?"verify":b.getString("phase","verify");start();}
 void check(boolean value,String name)throws Exception{if(!value)throw new Exception(name);passed++;Bundle b=new Bundle();b.putString("stream","PASS "+name+"\n");sendStatus(0,b);}
 void jsCheck(String expression,String name)throws Exception{check(h.js(expression).equals("true"),name);}
 void until(String expression)throws Exception{for(int i=0;i<100;i++){if(h.js(expression).equals("true"))return;Thread.sleep(100);}throw new Exception("Timed out: "+expression);}
