  h.call("clearMessages",new JSONObject());h.call("saveMessage",new JSONObject().put("message",new JSONObject().put("id","thought-upgrade-message").put("role","user").put("text","合成升级测试对话，不含真实用户数据").put("createdAt",System.currentTimeMillis())));
  JSONObject l=new JSONObject().put("id","thought-upgrade-learning").put("type","learning").put("date",day).put("title","升级保留知识管理学习").put("platform","合成测试").put("contentType","article").put("note","知识管理：原学习记录不能丢失").put("tags",new JSONArray().put("知识管理")).put("durationMinutes",35);
  JSONObject w=new JSONObject().put("id","thought-upgrade-work").put("type","work").put("date",day).put("title","升级保留工作").put("workStart",day+"T09:00:00").put("workEnd",day+"T18:00:00").put("breaks",new JSONArray().put(new JSONObject().put("start",day+"T12:00:00").put("end",day+"T13:00:00"))).put("durationMinutes",480);
  h.call("saveRecord",new JSONObject().put("record",l).put("allowDuplicate",true));h.call("saveRecord",new JSONObject().put("record",w).put("allowDuplicate",true));
  JSONObject profile=new JSONObject().put("id","deepseek").put("label","DeepSeek").put("baseUrl","https://example.invalid/v1").put("model","synthetic-offline-model").put("protocol","chat").put("effort","off").put("vision",false).put("allowHttp",false).put("apiKey","SYNTHETIC-LOCAL-NOT-A-REAL-KEY");
  h.call("saveSettings",new JSONObject().put("settings",new JSONObject().put("profile",profile).put("dailyLearningGoal",60)));
  try(TrackStore db=new TrackStore(getTargetContext())){db.deleteDay(day);long base=TrackStore.dayStart(day)+12*3600000;for(int i=0;i<10;i++)db.add(BeforeGapFixTest.p(base+i*5000,i*7,1.4f),"thought-upgrade-synthetic");JSONObject snapshot=new JSONObject().put("init",init()).put("raw",db.diagnostics(day).getJSONArray("rawPoints")).put("gpx",db.gpx(day));try(FileOutputStream f=getTargetContext().openFileOutput("thought-upgrade.json",0)){f.write(snapshot.toString().getBytes("UTF-8"));}}
